  { name: 'Orange', url: 'https://www.orange.es/tarifas' },
  { name: 'Movistar', url: 'https://www.movistar.es/fibra-y-movil/' },
  { name: 'Digi', url: 'https://www.digimobil.es/fibra-movil' },
