const out = [];

// 1. Obtenemos el HTML de la entrada
const htmlText = $input.first().json.data || $input.first().json.texto_limpio || $input.first().json.body || "";

if (!htmlText) {
    return [{ json: { error: "El HTML de Naturgy llegó vacío." } }];
}

// 2. PASO A: Extraer las condiciones de las tarjetas "shadow-card"
const cardBlocks = htmlText.split('shadow-card__content');
const condicionesMap = {};

for(let i = 1; i < cardBlocks.length; i++) {
    const block = cardBlocks[i];

    // Sacamos el título (Ej: Tarifa Por Uso Luz)
    const titleMatch = block.match(/shadow-card__title[^>]*>\s*(.*?)\s*<\/p>/);
    if (!titleMatch) continue;
    const title = titleMatch[1].trim();

    // Sacamos los 'bullet points' de la descripción
    let condiciones = [];
    const ulMatch = block.match(/<div class="shadow-card__description"[^>]*>([\s\S]*?)<\/div>/);
    if (ulMatch) {
        const liRegex = /<li>(.*?)<\/li>/g;
        let liM;
        while((liM = liRegex.exec(ulMatch[1])) !== null) {
            // Limpiamos etiquetas HTML y el molesto &nbsp;
            let text = liM[1].replace(/&nbsp;/g, ' ').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
            if(text) condiciones.push("- " + text);
        }
    }
    condicionesMap[title] = condiciones;
}

// 3. PASO B: Extraer precios y URLs de los bloques "exp229"
const expBlocks = htmlText.split('<div class="exp229');
const vistos = new Set();

for (let i = 1; i < expBlocks.length; i++) {
    const block = expBlocks[i];

    const titleMatch = block.match(/<p class="titulo"><b>(.*?)<\/b><\/p>/);
    if (!titleMatch) continue;

    // Naturgy a veces pone "Por Uso Luz" en el bloque de precio, pero "Tarifa Por Uso Luz" en la tarjeta. 
    // Lo unificamos para que haga match.
    let nombre_tarifa = titleMatch[1].trim();
    if (!nombre_tarifa.toLowerCase().includes("tarifa")) {
        nombre_tarifa = "Tarifa " + nombre_tarifa;
    }

    // Evitamos duplicados (Naturgy repite las tarjetas en versión móvil y desktop)
    if (vistos.has(nombre_tarifa)) continue;
    vistos.add(nombre_tarifa);

    let precio = null;
    let preciosAdicionales = null;

    // Buscamos matemáticamente el precio según el tipo de tarifa
    if (block.startsWith(' uso"')) {
        // Tarifa por uso (ej: 0,<span class="no-imp">109900 </span>)
        const pMatch = block.match(/0,<span class="no-imp">(\d+)\s*<\/span>/);
        if (pMatch) precio = parseFloat("0." + pMatch[1]);

    } else if (block.startsWith(' noche"')) {
        // Tarifa Noche (Valle, Llano, Punta)
        const arr = [];
        const pRegex = /<p class="precio">(Valle|Llano|Punta)[\s\S]*?<span class="no-imp">([\d,]+)\s*<\/span>/g;
        let pM;
        while((pM = pRegex.exec(block)) !== null) {
            let tipo = pM[1];
            let val = parseFloat(pM[2].replace(',', '.')); // Convertimos la coma europea a punto
            arr.push(`${tipo}: ${val}`);
            if (precio === null) precio = val; // Usamos el primer precio que encuentre como variable principal
        }
        if (arr.length > 0) preciosAdicionales = arr.join(' / ');

    } else if (block.startsWith(' plana"')) {
        // Tarifa Plana no tiene precio por kWh fijo, depende del cliente
        preciosAdicionales = "Cuota fija personalizada";
    }

    // Extraemos el enlace de la oferta
    let url_oferta = null;
    const urlMatch = block.match(/href="([^"]+)" class="mas-info"/);
    if (urlMatch) {
        url_oferta = urlMatch[1].startsWith('http') ? urlMatch[1] : "https://www.naturgy.es" + urlMatch[1];
    }

    // Recuperamos las condiciones que parseamos en el paso A
    let condicionesFinales = condicionesMap[nombre_tarifa] || [];

    // 4. CONSTRUIMOS LA SALIDA
    out.push({
        json: {
            nombre_tarifa: nombre_tarifa,
            precio: precio,
            precios_adicionales: preciosAdicionales,
            unidad_precio: "€/kWh",
            permanencia: condicionesFinales.join(' ').toLowerCase().includes('sin permanencia') ? 'Sin permanencia' : 'Consultar condiciones',
            condiciones: condicionesFinales.join('\n'),
            url_oferta_externa: url_oferta || $('Loop (Iterar una a una)1').first().json.targetUrl
        }
    });
}

if (out.length === 0) {
    return [{ json: { error: "No se encontraron tarifas. Revisa la estructura del HTML." } }];
}

return out;

const out = [];

// 1. Obtenemos el HTML (buscamos en diferentes propiedades por si acaso)
const htmlText = $input.first().json.data || $input.first().json.texto_limpio || $input.first().json.body || "";

if (!htmlText) {
    return [{ json: { error: "El HTML de Digi llegó vacío." } }];
}

// 2. PARSER DE DIGI (Fibra + Móvil)
// Digi envuelve sus combinaciones principales en la clase "card panelProductHorizontal gaList"
const digiCards = htmlText.split('class="card panelProductHorizontal gaList"');

// Usamos un Set para evitar duplicados en la extracción
const vistos = new Set();

for (let i = 1; i < digiCards.length; i++) {
    const card = digiCards[i];

    // Precio total mensual
    const priceMatch = card.match(/<div class="amount">(\d+)<\/div>/);
    if (!priceMatch) continue;
    const precio = parseFloat(priceMatch[1]);

    // Construir el nombre de la tarifa uniendo los productos que contiene la tarjeta
    const products = [];
    const productDivs = card.split('product_ga"');

    for(let j = 1; j < productDivs.length; j++) {
        const pDiv = productDivs[j];

        // Buscamos el nombre base y si tiene multiplicadores (líneas extra)
        const nameMatch = pDiv.match(/data-name="([^"]+)"/);
        const unitMatch = pDiv.match(/data-units="([^"]+)"/);

        if (nameMatch) {
            let name = nameMatch[1].trim();
            // Si hay más de una línea (ej: 2x IlimiTODO), lo añadimos al nombre
            if (unitMatch && parseInt(unitMatch[1]) > 1) {
                name = unitMatch[1] + "x " + name;
            }
            products.push(name);
        }
    }

    // Ejemplo de salida: "Fibra SMART 500Mb + 2x IlimiTODO"
    const nombre_tarifa = products.join(' + ');

    if (vistos.has(nombre_tarifa)) continue;
    vistos.add(nombre_tarifa);

    // Condiciones: Extraemos los textos descriptivos de Fibra y Móvil limpios de HTML
    let condiciones = [];

    // Texto de la fibra (ej: Fibra SMART 500 Mbps)
    const speedMatch = card.match(/<div class="speed">([\s\S]*?)<\/div>/);
    if (speedMatch) {
        condiciones.push("- " + speedMatch[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim());
    }

    // Texto del móvil (ej: Móvil 50 GB acumulables...)
    const movilMatch = card.match(/(Móvil\s*<b>[\s\S]*?)<\/div>/);
    if (movilMatch) {
        condiciones.push("- " + movilMatch[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim());
    }

    // URL de contratación directa
    let url_oferta = null;
    const urlMatch = card.match(/href="(\/combina-telefonia-internet[^"]+)"/);
    if (urlMatch) {
        // Limpiamos los "&amp;" a un "&" normal
        url_oferta = "https://www.digimobil.es" + urlMatch[1].replace(/&amp;/g, '&');
    }

    out.push({
        json: {
            compania: "Digi",
            nombre_tarifa: nombre_tarifa,
            precio: precio,
            precios_adicionales: null, // Digi da un precio cerrado por el combo
            unidad_precio: "€/mes",
            permanencia: "3 meses (Fibra) / Sin permanencia (Móvil)", // Fijo en las políticas de Digi
            condiciones: condiciones.join('\n'),
            url_oferta_externa: url_oferta || $('Loop (Iterar una a una)1').first().json.targetUrl
        }
    });
}

// Chivato de seguridad
if (out.length === 0) {
    return [{ json: { error: "El parser se ejecutó, pero no logró encontrar tarifas de Digi. Revisa la estructura." } }];
}

return out;

const out = [];

// 1. Obtenemos el HTML de la entrada
const htmlText = $input.first().json.data || $input.first().json.texto_limpio || $input.first().json.body || "";

if (!htmlText) {
    return [{ json: { error: "El HTML de Movistar llegó vacío." } }];
}

// 2. Buscamos el "tesoro": el objeto JSON que Next.js inyecta en la página
const nextDataMatch = htmlText.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);

if (nextDataMatch) {
    try {
        const jsonData = JSON.parse(nextDataMatch[1]);

        // Navegamos por el árbol del JSON hasta los packs "Más vendidos" (las tarifas armadas)
        const bestSellers = jsonData.props?.pageProps?.initialState?.recomendator?.data?.recomAndBestSellers?.bestSellers || [];

        bestSellers.forEach(pack => {
            const rec = pack.recommendation;
            if (!rec) return;

            // Extraemos precio actual y precio original (por si hay una promoción aplicada)
            const precioActual = rec["cms-atom-price-1"]?.price || null;
            const precioSinPromo = rec["cms-atom-price-2"]?.price || null;

            // Extraemos los bloques de texto. Vienen con HTML (<ul>, <li>, <strong>), así que lo limpiamos
            const texto1 = rec["cms-atom-text-1"]?.text || "";
            const texto2 = rec["cms-atom-text-2"]?.text || "";

            // Función auxiliar para limpiar etiquetas HTML y espacios extra
            const cleanHTML = (htmlStr) => {
                return htmlStr
                    .replace(/<[^>]+>/g, ' ') // Quita etiquetas
                    .replace(/&nbsp;/g, ' ')  // Quita espacios non-breaking
                    .replace(/\s+/g, ' ')     // Colapsa múltiples espacios
                    .trim();
            };

            const descripcionComunicaciones = cleanHTML(texto1); // Info de Fibra y Móvil
            const descripcionTVDispositivos = cleanHTML(texto2); // Info de TV y Dispositivos

            // Extraemos permanencia y la URL de contratación/info
            const permanencia = rec["cms-atom-text-4"]?.text || "Consultar condiciones";
            let url = rec["cms-atom-button-2"]?.href || null;

            // Movistar a veces usa URLs relativas internas para sus modales, las formateamos bien
            if (url && url.includes("cms-modal-page:")) {
                url = url.replace("cms-modal-page:", "https://www.movistar.es");
                // Limpiamos los parámetros internos del modal para dejar una URL limpia
                url = url.split("?")[0]; 
            }

            out.push({
                json: {
                    compania: "Movistar",
                    nombre_tarifa: "Pack miMovistar", // Movistar usa combinaciones modulares bajo este nombre
                    descripcion_comunicaciones: descripcionComunicaciones,
                    descripcion_tv_y_dispositivos: descripcionTVDispositivos,
                    precio_actual: precioActual,
                    precio_sin_promo: precioSinPromo !== "" ? precioSinPromo : null,
                    unidad_precio: "€/mes",
                    permanencia: permanencia,
                    url_oferta_externa: url || $('Loop (Iterar una a una)1').first().json.targetUrl
                }
            });
        });

    } catch(e) {
        return [{ json: { error: "Error al parsear el JSON interno de Movistar: " + e.message } }];
    }
} else {
    return [{ json: { error: "No se encontró el bloque __NEXT_DATA__ en el HTML de Movistar." } }];
}

// Chivato de seguridad
if (out.length === 0) {
    return [{ json: { error: "El script se ejecutó, pero no encontró packs configurados en los datos de Movistar." } }];
}

return out;

const out = [];

// 1. Obtenemos el HTML de la entrada
const htmlText = $input.first().json.data || $input.first().json.texto_limpio || $input.first().json.body || "";

if (!htmlText) {
    return [{ json: { error: "El HTML de Orange llegó vacío." } }];
}

// 2. PARSER DE ORANGE
// Orange usa la clase "card-tariff-new" para sus contenedores de tarifas
const blocks = htmlText.split('class="card-tariff-new');

for (let i = 1; i < blocks.length; i++) {
    const block = blocks[i];

    // Extraer datos del input hidden (Nombre, ID y Precio base)
    const dataMatch = block.match(/dataSimpleTariff[^>]*data-price="([^"]+)"[^>]*data-name="([^"]+)"/);
    if (!dataMatch) continue;

    const precioBase = dataMatch[1];
    const nombreTecnico = dataMatch[2];

    // Extraer el Título comercial (Ej: Cine y Series con 1 línea)
    const titleMatch = block.match(/card-tariff-new__header[^>]*>\s*([\s\S]*?)\s*<\/div>/);
    const nombreComercial = titleMatch ? titleMatch[1].trim() : nombreTecnico;

    // Extraer características (Fibra, Móvil, TV)
    let condiciones = [];
    const featureRegex = /card-tariff-new__features__main[^>]*>\s*([\s\S]*?)\s*<\/div>/g;
    let featureM;
    while ((featureM = featureRegex.exec(block)) !== null) {
        let text = featureM[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        if (text) condiciones.push("- " + text);
    }

    // Extraer servicios de streaming incluidos (Netflix, Disney, etc.)
    const streamingMatch = block.match(/Incluído 1 servicio streaming/);
    if (streamingMatch) {
        // Buscamos iconos que NO tengan la clase "disabled"
        if (block.includes('iconassets__disney-plus') && !block.includes('card-tariff-simple__features__item--disabled"> <hl-icon name="iconassets__disney-plus')) {
            condiciones.push("- Incluye Disney+");
        }
        if (block.includes('iconassets__netflix-mini') && !block.includes('card-tariff-simple__features__item--disabled"> <hl-icon name="iconassets__netflix-mini')) {
            condiciones.push("- Incluye Netflix");
        }
    }

    // Extraer Precio Promocional (si existe)
    // Orange usa el componente <hl-price-block> para los precios finales
    const promoPriceMatch = block.match(/unit="(\d+)"[^>]*size="md"/);
    const precioFinal = promoPriceMatch ? promoPriceMatch[1] : precioBase;

    // Extraer URL de "Más info"
    let url_oferta = null;
    const urlMatch = block.match(/href="([^"]+)"[^>]*class="[^"]*js-more-info-tariff/);
    if (urlMatch) {
        url_oferta = urlMatch[1].startsWith('http') ? urlMatch[1] : "https://www.orange.es" + urlMatch[1];
    }

    out.push({
        json: {
            compania: "Orange",
            nombre_tarifa: nombreComercial,
            precio: parseFloat(precioFinal),
            precio_fuera_promo: parseFloat(precioBase),
            unidad_precio: "€/mes",
            permanencia: block.toLowerCase().includes("sin permanencia") ? "Sin permanencia" : "12 meses",
            condiciones: condiciones.join('\n'),
            url_oferta_externa: url_oferta || $('Loop (Iterar una a una)1').first().json.targetUrl
        }
    });
}

// Limpiar duplicados por nombre de tarifa
const uniqueOut = Array.from(new Map(out.map(item => [item.json.nombre_tarifa, item])).values());

if (uniqueOut.length === 0) {
    return [{ json: { error: "No se detectaron tarifas de Orange. Revisa si el HTML contiene la clase 'card-tariff-new'." } }];
}

return uniqueOut;

const items = $input.all();
const out = [];

for (const item of items) {
  // El HTML limpio que recibimos de ZenRows
  const htmlText = item.json.data || item.json.body || item.json.response || item.json.texto_limpio;

  if (!htmlText) continue;

  // Dividimos el HTML gigante en "trozos", cada uno representando una tarjeta de tarifa
  // Endesa guarda el nombre de la tarifa en el atributo data-product-name
  const cards = htmlText.split('data-product-name="');

  // Ignoramos el primer trozo (que es la cabecera de la web)
  for (let i = 1; i < cards.length; i++) {
    const cardHtml = cards[i];

    // 1. EXTRAER NOMBRE TARIFA
    const nombre_tarifa = cardHtml.substring(0, cardHtml.indexOf('"')).trim();

    // 2 y 3. EXTRAER PRECIO Y UNIDAD (Buscamos el primer precio destacado)
    let precio = null;
    let unidad_precio = null;

    const priceBlockMatch = cardHtml.match(/class="[^"]*price__detail__price__discounted[^>]*>([\s\S]*?)<\/p>/);
    if (priceBlockMatch) {
        const priceValMatch = priceBlockMatch[1].match(/<span class="price">\s*([\d,.]+)\s*<\/span>/);
        const unitValMatch = priceBlockMatch[1].match(/<span class="type">\s*([^<]+)\s*<\/span>/);

        if (priceValMatch) {
            // Endesa usa comas para los decimales (ej. 0,126600). Lo pasamos a punto para MySQL
            let cleaned = priceValMatch[1].replace(/[^0-9,]/g, '').replace(',', '.');
            precio = parseFloat(cleaned);
        }
        if (unitValMatch) {
            unidad_precio = unitValMatch[1].trim();
        }
    }

    // 4 y 5. EXTRAER PERMANENCIA Y CONDICIONES (Listado de ventajas)
    let permanencia = "Consultar condiciones"; // Valor por defecto
    let condicionesList = [];

    // Buscamos todos los textos de la lista de características de esa tarifa
    const listItemsMatches = cardHtml.matchAll(/<p class="[^"]*list__item__text">([\s\S]*?)<\/p>/g);
    for (const match of listItemsMatches) {
        let text = match[1].trim();
        condicionesList.push("- " + text);
        // Si alguna viñeta habla de permanencia, la guardamos en su campo específico
        if (text.toLowerCase().includes("permanencia")) {
            permanencia = text;
        }
    }

    // Extraemos también la "letra pequeña" y notas legales que Endesa oculta en el data-fullnote
    const noteMatch = cardHtml.match(/data-fullnote="([^"]+)"/);
    if (noteMatch) {
        // Limpiamos los tags HTML que Endesa mete dentro de ese atributo (&lt;strong&gt; etc)
        let nota = noteMatch[1].replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');
        nota = nota.replace(/<[^>]+>/g, ''); 
        condicionesList.push("\nLegal: " + nota);
    }
    const condiciones = condicionesList.join('\n');

    // 6. EXTRAER URL DE LA OFERTA EXTERNA
    let url_oferta_externa = null;
    const urlMatch = cardHtml.match(/<a[^>]+href="([^"]+)"[^>]*class="[^"]*button__primary[^"]*"/i);
    if (urlMatch) {
        let extractedUrl = urlMatch[1].trim();
        // Si el enlace es relativo (ej. /es/luz...), le añadimos el dominio principal
        if (extractedUrl.startsWith('/')) {
            extractedUrl = "https://www.endesa.com" + extractedUrl;
        }
        url_oferta_externa = extractedUrl;
    }

    // Filtro de calidad: Solo enviamos a MySQL aquellas tarjetas donde sí hemos encontrado un precio.
    if (nombre_tarifa && precio !== null) {
        out.push({
            json: {
                nombre_tarifa: nombre_tarifa,
                precio: precio,
                unidad_precio: unidad_precio,
                permanencia: permanencia,
                condiciones: condiciones,
                url_oferta_externa: url_oferta_externa || $('Loop (Iterar una a una)1').first().json.targetUrl

            }
        });
    }
  }
}

return out;
